// Prometheus に投げるクエリ。1 件が 1 回の HTTP Request になる
return [
  { key: 'uptime', query: 'avg_over_time(probe_success[7d])' },
  // 失敗していた分数（1 分刻み）。導入して 7 日に満たないサービスでも正しく数えられる
  { key: 'down', query: 'sum_over_time((1 - probe_success)[7d:1m])' },
  { key: 'mem', query: '1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes' },
  { key: 'memPrev', query: '1 - node_memory_MemAvailable_bytes offset 7d / node_memory_MemTotal_bytes offset 7d' },
  { key: 'disk', query: '1 - node_filesystem_avail_bytes{mountpoint="/"} / node_filesystem_size_bytes{mountpoint="/"}' },
  { key: 'diskPrev', query: '1 - node_filesystem_avail_bytes{mountpoint="/"} offset 7d / node_filesystem_size_bytes{mountpoint="/"} offset 7d' },
  { key: 'cert', query: 'bottomk(1, (probe_ssl_earliest_cert_expiry - time()) / 86400)' },
  // Watchdog は常に発火しているので除く。サンプル数 × 15 秒（評価間隔）が発火していた時間
  { key: 'alerts', query: 'sum by (alertname) (count_over_time(ALERTS{alertstate="firing",alertname!="Watchdog"}[7d]))' },
].map(json => ({ json }));

// 8 つの結果（クエリ定義と同じ順）を、1 通の Slack 文面にまとめる
const keys = $('クエリ定義').all().map(i => i.json.key);
const r = {};
$input.all().forEach((item, n) => { r[keys[n]] = item.json.data.result; });

const byHost = rows => Object.fromEntries(rows.map(x => [x.metric.host, Math.round(parseFloat(x.value[1]) * 100)]));
const fmtDate = d => d.toLocaleDateString('ja-JP', { timeZone: 'Asia/Tokyo', month: 'numeric', day: 'numeric' });
const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 3600 * 1000);
const lines = [`*📊 homelab 週次レポート（${fmtDate(start)}〜${fmtDate(end)}）*`];

// 稼働率: 失敗が 10 分以上のものだけ並べる（導入直後は標本が少なく、割合が大きく振れるため、分数で判定する）
const downMin = Object.fromEntries(r.down.map(x => [x.metric.service, Math.round(parseFloat(x.value[1]))]));
const svc = r.uptime.map(x => ({ name: x.metric.service, u: parseFloat(x.value[1]) }));
const bad = svc.filter(x => (downMin[x.name] ?? 0) >= 10).sort((a, b) => downMin[b.name] - downMin[a.name]);
lines.push('', '*稼働率（外形監視、7 日）*');
lines.push(`  ✅ ${svc.length - bad.length} / ${svc.length} サービスは失敗 10 分未満`);
for (const x of bad) lines.push(`  ⚠️ ${x.name} ${(x.u * 100).toFixed(2)}%（失敗は約 ${downMin[x.name] ?? 0} 分）`);

// リソース: 使用率（先週との差）。ディスクが 5 ポイント以上増えた、ディスク 80% 以上、メモリ 85% 以上に印を付ける
const mem = byHost(r.mem), memPrev = byHost(r.memPrev), disk = byHost(r.disk), diskPrev = byHost(r.diskPrev);
const show = (cur, prev) => {
  if (cur === undefined) return '-';
  if (prev === undefined) return `${cur}%`;
  const d = cur - prev;
  return `${cur}%（${d >= 0 ? '+' : ''}${d}）`;
};
lines.push('', '*リソース（先週との差）*');
for (const h of [...new Set([...Object.keys(mem), ...Object.keys(disk)])].sort()) {
  const flag = (disk[h] - (diskPrev[h] ?? disk[h]) >= 5) || disk[h] >= 80 || mem[h] >= 85 ? ' ⚠️' : '';
  lines.push(`  ${h}  メモリ ${show(mem[h], memPrev[h])} / ディスク ${show(disk[h], diskPrev[h])}${flag}`);
}

// 証明書: いちばん期限の近いもの。Caddy は残り 30 日で更新するので、21 日を切ったら更新の失敗を疑う
const c = r.cert[0];
if (c) {
  const days = Math.floor(parseFloat(c.value[1]));
  lines.push('', '*証明書の期限*', `  ${days < 21 ? '⚠️' : '✅'} 最短は ${c.metric.service} の残り ${days} 日`);
}

// 先週のアラート: 発火していた時間（評価間隔 15 秒）。ターゲットごとの時間の合計（延べ）
lines.push('', '*先週のアラート*');
const alerts = r.alerts.map(x => ({ name: x.metric.alertname, min: Math.round(parseFloat(x.value[1]) * 15 / 60) })).sort((a, b) => b.min - a.min);
if (!alerts.length) lines.push('  なし');
for (const a of alerts) lines.push(`  ${a.name}: 延べ約 ${a.min} 分`);

return [{ json: { text: lines.join('\n') } }];
